result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app/service.py", "content": """"Event sourcing core: the fold, event loading, and command handling.

State is ALWAYS derived by folding events -- nothing else is authoritative.
The UNIQUE(aggregate_id, seq) primary key on `events` makes an append fail if
another writer raced past our expected_version (optimistic concurrency).
"""
from __future__ import annotations

import json
import sqlite3
import threading

from .db import connect

DEPOSIT = "deposit"
WITHDRAW = "withdraw"
FREEZE = "freeze"

# Serializes read-fold-append inside one process. Cross-process safety comes
# from the UNIQUE(aggregate_id, seq) constraint.
_CMD_LOCK = threading.Lock()


class CommandError(Exception):
    """A command that must not produce an event."""

    def __init__(self, status_code: int, detail: str):
        super().__init__(detail)
        self.status_code = status_code
        self.detail = detail


def fold(events: list[dict]) -> dict:
    """Fold an ordered event list into aggregate state."""
    state = {"balance": 0, "frozen": False, "version": 0}
    for event in events:
        payload = json.loads(event["payload"])
        etype = event["type"]
        if etype == DEPOSIT:
            state["balance"] += payload["amount"]
        elif etype == WITHDRAW:
            state["balance"] -= payload["amount"]
        elif etype == FREEZE:
            state["frozen"] = True
        else:
            raise ValueError(f"unknown event type: {etype!r}")
        state["version"] += 1  # version == last applied seq
    return state


def load_events(conn: sqlite3.Connection, account_id: str) -> list[dict]:
    rows = conn.execute(
        "SELECT seq, type, payload FROM events WHERE aggregate_id = ? ORDER BY seq",
        (account_id,),
    ).fetchall()
    return [dict(r) for r in rows]


def get_state(conn: sqlite3.Connection, account_id: str) -> dict:
    """Current state of an account, derived on the fly from its events."""
    return fold(load_events(conn, account_id))


def _validate(state: dict, command: str, amount: int | None) -> None:
    """Business rules. A rejection appends NOTHING to the log."""
    if command == WITHDRAW:
        if state["frozen"]:
            raise CommandError(400, "account is frozen")
        if amount > state["balance"]:
            raise CommandError(
                400,
                f"insufficient funds: balance {state['balance']}, tried to withdraw {amount}",
            )


def append(
    conn: sqlite3.Connection,
    account_id: str,
    event_type: str,
    payload: dict,
    expected_version: int,
) -> dict:
    """Validate against folded state, then optimistically append one event.

    Raises CommandError(409) on a version conflict or a concurrent-write race.
    Returns the new state after folding the appended event.
    """
    with _CMD_LOCK:
        state = get_state(conn, account_id)
        current = state["version"]
        if expected_version != current:
            raise CommandError(
                409,
                f"version conflict: expected {expected_version}, current {current}",
            )
        _validate(state, event_type, payload.get("amount"))

        try:
            conn.execute(
                "INSERT INTO events (aggregate_id, seq, type, payload) VALUES (?, ?, ?, ?)",
                (account_id, current + 1, event_type, json.dumps(payload)),
            )
            conn.commit()
        except sqlite3.IntegrityError:
            conn.rollback()
            raise CommandError(
                409,
                f"concurrent write: seq {current + 1} already taken for account {account_id}",
            )
        return get_state(conn, account_id)


# --- Command facades -------------------------------------------------------

def deposit(conn, account_id: str, amount: int, expected_version: int) -> dict:
    return append(conn, account_id, DEPOSIT, {"amount": amount}, expected_version)


def withdraw(conn, account_id: str, amount: int, expected_version: int) -> dict:
    return append(conn, account_id, WITHDRAW, {"amount": amount}, expected_version)


def freeze(conn, account_id: str, expected_version: int) -> dict:
    return append(conn, account_id, FREEZE, {}, expected_version)
"})
