from __future__ import annotations

from contextlib import asynccontextmanager

from fastapi import FastAPI, HTTPException, Request
from pydantic import BaseModel, Field

from . import service
from .db import connect
from .service import CommandError

_conn = None


def get_conn():
    global _conn
    if _conn is None:
        _conn = connect()
    return _conn


@asynccontextmanager
async def lifespan(_app: FastAPI):
    get_conn()  # open eagerly so the first request doesn't pay for it
    yield


app = FastAPI(title="Event-sourced bank account", version="1.0.0", lifespan=lifespan)


class AmountCommand(BaseModel):
    amount: int = Field(gt=0, description="Amount in minor units; must be positive")
    expected_version: int = Field(ge=0, description="Version the caller last saw")


class FreezeCommand(BaseModel):
    expected_version: int = Field(ge=0)


def _projection(account_id: str, state: dict) -> dict:
    return {
        "account_id": account_id,
        "balance": state["balance"],
        "frozen": state["frozen"],
        "version": state["version"],
    }


def _run(account_id: str, fn) -> dict:
    try:
        state = fn(get_conn(), account_id)
    except CommandError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail)
    return _projection(account_id, state)


@app.post("/accounts/{account_id}/deposit")
def deposit(account_id: str, cmd: AmountCommand):
    return _run(account_id, lambda c: service.deposit(c, account_id, cmd.amount, cmd.expected_version))


@app.post("/accounts/{account_id}/withdraw")
def withdraw(account_id: str, cmd: AmountCommand):
    return _run(account_id, lambda c: service.withdraw(c, account_id, cmd.amount, cmd.expected_version))


@app.post("/accounts/{account_id}/freeze")
def freeze(account_id: str, cmd: FreezeCommand):
    return _run(account_id, lambda c: service.freeze(c, account_id, cmd.expected_version))


@app.get("/accounts/{account_id}")
def get_account(account_id: str):
    conn = get_conn()
    events = service.load_events(conn, account_id)
    if not events:
        raise HTTPException(status_code=404, detail=f"unknown account {account_id!r}")
    return _projection(account_id, service.fold(events))


@app.get("/accounts/{account_id}/events")
def get_events(account_id: str):
    conn = get_conn()
    events = service.load_events(conn, account_id)
    if not events:
        raise HTTPException(status_code=404, detail=f"unknown account {account_id!r}")
    return [
        {"seq": e["seq"], "type": e["type"], "payload": e["payload"]}
        for e in events
    ]
"})
